SQL:
-- sgl.query(name: Setting, command: one)
SELECT current_setting('search_path') AS path, current_setting('app.tenant', true) AS tenant,
       pg_size_pretty(1024::bigint) AS size;

-- sgl.query(name: Elements, command: many)
SELECT id, jsonb_array_elements(payload -> 'items') AS item, jsonb_object_keys(payload) AS key
FROM events;

-- sgl.query(name: Series, command: many)
SELECT generate_series(1, 3) AS n, generate_series(created_at, created_at + interval '2 days', interval '1 day') AS day
FROM events;

-- sgl.query(name: Ages, command: many)
SELECT id, age(created_at, '2024-01-01') AS since_new_year, date_bin('15 minutes', happened, '2000-01-01') AS slot
FROM events;
